use xiom.io;

use xiom.string;
fn cast_vote(
  registered: Set[Str],
  has_voted: Set[Str],
  votes: Map[Str,Int],
  voter: Str,
  candidate: Str
) -> Bool
  requires: registered.contains(voter);
  requires: !has_voted.contains(voter);
{
  has_voted.insert(voter);
  match votes.get(candidate) {
    Some(count) => votes.insert(candidate, count + 1);
    None => votes.insert(candidate, 1);
  }
  return true;
}

fn main() -> Int {
  let registered: Set[Str] = Set[Str].new();
  let has_voted: Set[Str] = Set[Str].new();
  let votes: Map[Str,Int] = Map[Str,Int].new();

  registered.insert("alice");
  registered.insert("bob");

  cast_vote(registered, has_voted, votes, "alice", "Kim");
  cast_vote(registered, has_voted, votes, "bob", "Kim");

  match votes.get("Kim") {
    Some(count) => io.println("Kim: " + to_string(count));
    None => io.println("Kim: 0");
  }

  return 0;
}
